function check(input, actual, expected) {
  const [nums] = input;
  if (!Array.isArray(actual) || !Array.isArray(expected) || actual.length !== expected.length) return false;
  const pool = new Set(nums);
  const sorted = [...actual].sort((a, b) => a - b);
  for (let i = 0; i < sorted.length; i++) {
    if (!pool.has(sorted[i])) return false;
    // In sorted order each value must divide the next; divisibility then holds for every pair.
    if (i > 0 && (sorted[i] === sorted[i - 1] || sorted[i] % sorted[i - 1] !== 0)) return false;
  }
  return true;
}

