function validate([nums]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 2000000000)) return 'Each value is a whole number from 1 to 2 * 10^9.';
  if (new Set(nums).size !== nums.length) return 'The values in nums must be distinct.';
  return null;
}

