function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1000 : 1 + pick(10);
  const top = size === 'large' ? (rand() < 0.5 ? 2000000000 : 5000) : [12, 40, 100][pick(3)];
  const seen = new Set();
  // Sometimes seed a divisibility chain so long answers appear, then fill with random values.
  if (rand() < 0.5) {
    let value = 1 + pick(3);
    while (seen.size < n / 2 && value <= top) {
      seen.add(value);
      value *= 2 + pick(2);
    }
  }
  while (seen.size < n) seen.add(1 + pick(top));
  const nums = [...seen];
  for (let i = nums.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
